package main

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/exec"
	"regexp"
	"strings"
	"sync"
	"time"
)

type AuditEntry struct {
	Timestamp time.Time
	User      string
	Action    string
	Resource  string
	Resolved  string
}

type ExprContext struct {
	Namespace string
	Cluster   string
	Region    string
	Labels    map[string]string
}

var (
	auditLog   []AuditEntry
	auditMutex sync.Mutex
	safeExprRe = regexp.MustCompile(`^[a-zA-Z0-9_.\-\s=<>!&|()"']+$`)
)

func generateRequestID() string {
	b := make([]byte, 8)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func resolveExpression(expr string, ctx *ExprContext) (string, error) {
	result := expr
	// Phase 1: resolve namespace references
	result = strings.ReplaceAll(result, "${namespace}", ctx.Namespace)
	result = strings.ReplaceAll(result, "${cluster}", ctx.Cluster)
	result = strings.ReplaceAll(result, "${region}", ctx.Region)

	// Phase 2: resolve label selectors
	for key, val := range ctx.Labels {
		placeholder := fmt.Sprintf("${labels.%s}", key)
		result = strings.ReplaceAll(result, placeholder, val)
	}

	return result, nil
}

func validateExpression(expr string) bool {
	// Strip known safe placeholders before validation
	cleaned := expr
	placeholderRe := regexp.MustCompile(`\$\{[a-zA-Z_.]+\}`)
	cleaned = placeholderRe.ReplaceAllString(cleaned, "PLACEHOLDER")
	return safeExprRe.MatchString(cleaned)
}

func applySchedulingPolicy(resolved string, reqID string) error {
	// Build constraint expression for the scheduler
	constraintArg := fmt.Sprintf("--constraint=%s", resolved)
	logger := log.New(os.Stdout, fmt.Sprintf("[%s] ", reqID), log.LstdFlags)
	logger.Printf("Applying scheduling constraint: %s", constraintArg)

	// Execute scheduler with resolved constraint
	cmd := exec.CommandContext(
		context.Background(),
		"/usr/local/bin/kube-scheduler",
		"apply",
		constraintArg,
	)
	cmd.Env = append(os.Environ(), fmt.Sprintf("REQUEST_ID=%s", reqID))
	output, err := cmd.CombinedOutput()
	if err != nil {
		logger.Printf("Scheduler output: %s", string(output))
		return fmt.Errorf("scheduler error: %w", err)
	}
	return nil
}

func buildAuditFormatString(entry AuditEntry) string {
	// Construct audit log format with resolved expression for traceability
	return fmt.Sprintf("[%s] user=%s action=%s resource=%s resolved=%s",
		entry.Timestamp.Format(time.RFC3339),
		entry.User,
		entry.Action,
		entry.Resource,
		entry.Resolved)
}

func handleSchedule(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	reqID := generateRequestID()
	user := r.Header.Get("X-Authenticated-User")
	if user == "" {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	expr := r.FormValue("constraint_expr")
	namespace := r.FormValue("namespace")
	cluster := r.FormValue("cluster")
	region := r.FormValue("region")

	if expr == "" || namespace == "" {
		http.Error(w, "Missing required fields", http.StatusBadRequest)
		return
	}

	// Validate the expression template BEFORE resolution
	if !validateExpression(expr) {
		http.Error(w, "Invalid expression syntax", http.StatusBadRequest)
		return
	}

	ctx := &ExprContext{
		Namespace: namespace,
		Cluster:   cluster,
		Region:    region,
		Labels:    make(map[string]string),
	}

	// Parse label parameters
	for key, values := range r.Form {
		if strings.HasPrefix(key, "label.") {
			labelKey := strings.TrimPrefix(key, "label.")
			ctx.Labels[labelKey] = values[0]
		}
	}

	resolved, err := resolveExpression(expr, ctx)
	if err != nil {
		http.Error(w, "Expression resolution failed", http.StatusInternalServerError)
		return
	}

	// Record audit entry
	entry := AuditEntry{
		Timestamp: time.Now(),
		User:      user,
		Action:    "schedule",
		Resource:  namespace,
		Resolved:  resolved,
	}
	auditMutex.Lock()
	auditLog = append(auditLog, entry)
	auditMutex.Unlock()

	log.Printf("%s", buildAuditFormatString(entry))

	// Apply the resolved scheduling policy
	if err := applySchedulingPolicy(resolved, reqID); err != nil {
		http.Error(w, "Scheduling failed", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusAccepted)
	fmt.Fprintf(w, "{\"request_id\": \"%s\", \"status\": \"accepted\"}\n", reqID)
}

func handleAuditLog(w http.ResponseWriter, r *http.Request) {
	auditMutex.Lock()
	defer auditMutex.Unlock()

	w.Header().Set("Content-Type", "application/json")
	for _, entry := range auditLog {
		fmt.Fprintf(w, "%s\n", buildAuditFormatString(entry))
	}
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/api/v1/schedule", handleSchedule)
	mux.HandleFunc("/api/v1/audit", handleAuditLog)

	server := &http.Server{
		Addr:         ":8443",
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
	}

	log.Printf("Starting orchestration controller on :8443")
	if err := server.ListenAndServe(); err != nil {
		log.Fatalf("Server failed: %v", err)
	}
}
